import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CeXt7FPx.js";const u=JSON.parse('{"title":"What tiffin elevate changes","description":"","frontmatter":{},"headers":[],"relativePath":"reference/elevate.md","filePath":"reference/elevate.md"}'),i={name:"reference/elevate.md"};function d(s,e,r,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="what-tiffin-elevate-changes" tabindex="-1">What <code>tiffin elevate</code> changes <a class="header-anchor" href="#what-tiffin-elevate-changes" aria-label="Permalink to &quot;What `tiffin elevate` changes&quot;">​</a></h1><p><code>tiffin elevate</code> sets your computer up for Tiffin, once. It shows the steps first, then asks for your password (an administrator prompt on Windows) and hands them to <code>tiffin-helper</code>, the only part of Tiffin that ever runs with those rights. The helper does one step per run, takes no input but its own typed arguments, uses no network, and checks it was installed where only an administrator can change it.</p><p><code>tiffin unelevate</code> undoes every step, removing only what Tiffin added.</p><h2 id="trust-tiffin-s-certificate-authority" tabindex="-1">Trust Tiffin&#39;s certificate authority <a class="header-anchor" href="#trust-tiffin-s-certificate-authority" aria-label="Permalink to &quot;Trust Tiffin&#39;s certificate authority&quot;">​</a></h2><p>Tiffin makes its own certificate authority, on your computer, for your sites&#39; HTTPS. It is limited to <code>.test</code> and <code>localhost</code> names and loopback addresses, so it can&#39;t vouch for any other site.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>macOS</td><td>added to the System keychain, trusted for SSL</td></tr><tr><td>Windows</td><td>added to the computer&#39;s Trusted Root store, for server authentication</td></tr><tr><td>Linux</td><td>added to your distribution&#39;s certificate bundle; on Linux, also to Firefox&#39;s policy</td></tr></tbody></table><h2 id="send-test-names-to-tiffin" tabindex="-1">Send <code>.test</code> names to Tiffin <a class="header-anchor" href="#send-test-names-to-tiffin" aria-label="Permalink to &quot;Send `.test` names to Tiffin&quot;">​</a></h2><p>Only <code>.test</code> names; every other lookup is untouched.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>macOS</td><td><code>/etc/resolver/test</code> points at tiffind (<code>127.0.0.1:1053</code>)</td></tr><tr><td>Windows</td><td>a <code>.test</code> rule in the DNS client&#39;s name resolution policy; where Group Policy controls those rules, your sites are listed in the hosts file instead</td></tr><tr><td>Linux</td><td>a systemd-resolved drop-in, <code>resolved.conf.d/tiffin.conf</code> (<code>Domains=~test</code>)</td></tr></tbody></table><h2 id="let-tiffind-use-ports-53-80-and-443-linux" tabindex="-1">Let tiffind use ports 53, 80 and 443 (Linux) <a class="header-anchor" href="#let-tiffind-use-ports-53-80-and-443-linux" aria-label="Permalink to &quot;Let tiffind use ports 53, 80 and 443 (Linux)&quot;">​</a></h2><p>A capability on the <code>tiffind</code> program itself (<code>cap_net_bind_service</code>), not a system-wide setting, so no other program gains anything. The Linux packages give it back after each upgrade. macOS and Windows need no such step.</p><h2 id="fix-what-is-in-the-way-linux-only-when-needed" tabindex="-1">Fix what is in the way (Linux, only when needed) <a class="header-anchor" href="#fix-what-is-in-the-way-linux-only-when-needed" aria-label="Permalink to &quot;Fix what is in the way (Linux, only when needed)&quot;">​</a></h2><p><code>tiffin elevate</code> lists each of these before it asks for your password, and adds a step only if it applies:</p><ul><li><strong>Stop and disable another local tool&#39;s system services</strong> that run or start at boot and hold ports 80 and 443. Their files stay, so you can turn them back on. Tiffin restarts itself afterwards to take the ports.</li><li><strong>Make <code>/etc/systemd/resolved.conf.d</code> root&#39;s own</strong> (<code>chown root:root</code>, <code>chmod go-w</code>) when another user owns it or can write to it. Tiffin will not put the <code>.test</code> setting into a folder someone else can change. It changes only that folder, and only if every folder above it is already root&#39;s.</li><li><strong>Install <code>certutil</code></strong> (<code>libnss3-tools</code> or <code>nss-tools</code>) with <code>apt-get</code>, <code>dnf</code>, <code>pacman</code> or <code>zypper</code>, so Chrome and Chromium can trust the CA. The package manager downloads it. With none of these, Tiffin tells you which package to install.</li></ul><p><code>tiffin doctor --fix</code> runs <code>tiffin elevate</code> for these, then installs PHP (<code>tiffin add php</code>) if none is installed.</p><h2 id="install-the-helper-when-needed" tabindex="-1">Install the helper (when needed) <a class="header-anchor" href="#install-the-helper-when-needed" aria-label="Permalink to &quot;Install the helper (when needed)&quot;">​</a></h2><p>When the helper isn&#39;t already somewhere only an administrator can change (a package puts it there), <code>tiffin elevate</code> copies it to <code>/usr/local/libexec/tiffin</code> or <code>Program Files\\Tiffin</code> first.</p>',17)])])}const p=t(i,[["render",d]]);export{u as __pageData,p as default};
